    Question(id: 'aex_007', category: 'anatomy', subcategory: 'skeletal_system', type: 'test', difficulty: 'medium', questionText: 'Aşağıdakilerden hangisi yassı kemiklere örnektir?', options: ['Femur', 'Vertebra', 'Scapula', 'Talus'], correctAnswer: 'Scapula', explanation: 'Yassı kemikler: Scapula, sternum, costalar, pelvis ve kafatası kemikleri. Uzun: Femur, tibia. Kısa: Karpal, tarsal. Düzensiz: Vertebra.'),
