    Question(id: 'aex_034', category: 'anatomy', subcategory: 'skeletal_system', type: 'test', difficulty: 'medium', questionText: 'Ayak tabanındaki kemerli yapıyı destekleyen ana ligament hangisidir?', options: ['Lig. cruciatum anterius', 'Lig. plantare longum', 'Lig. patellae', 'Lig. collaterale mediale'], correctAnswer: 'Lig. plantare longum', latinTerm: 'Ligamentum plantare longum', explanation: 'Lig. plantare longum, ayak tabanının longitudinal arkını (kemeri) destekleyen en uzun plantar ligamenttir.'),
    Question(id: 'aex_035', category: 'anatomy', subcategory: 'skeletal_system', type: 'test', difficulty: 'hard', questionText: 'N. ischiadicus (siyatik sinir) hangi yapının altından geçer?', options: ['Quadriceps femoris', 'M. piriformis', 'M. gluteus maximus', 'Lig. inguinale'], correctAnswer: 'M. piriformis', latinTerm: 'Nervus ischiadicus', explanation: 'N. ischiadicus (vücudun en kalın siniri), pelvis\'ten m. piriformis\'in altından çıkarak gluteal bölgeye geçer. Piriformis sendromunda bu sinir sıkışabilir.'),

    // ============================================================
