    Question(id: 'aex_036', category: 'anatomy', subcategory: 'muscular_system', type: 'test', difficulty: 'medium', questionText: 'Kas-tendon-kemik ilişkisinde kasın sabit noktasına ne denir?', options: ['İnsersiyo', 'Origo', 'Tendon', 'Fasya'], correctAnswer: 'Origo', explanation: 'Origo (origin) kasın sabit noktası, insersiyo kasın hareketli noktasıdır. Kasılma sırasında insersiyo noktası origoya doğru çekilir.'),
    Question(id: 'aex_037', category: 'anatomy', subcategory: 'muscular_system', type: 'test', difficulty: 'medium', questionText: 'Yassı ve geniş tendon yapısına ne denir?', options: ['Fasya', 'Aponeuroz', 'Ligament', 'Retinaculum'], correctAnswer: 'Aponeuroz', latinTerm: 'Aponeurosis', explanation: 'Aponeuroz, yassı kasların geniş tendon yapısıdır. Örnek: Galea aponeurotica (kafa derisi), palmar aponeuroz (avuç içi).'),
    Question(id: 'aex_038', category: 'anatomy', subcategory: 'muscular_system', type: 'test', difficulty: 'easy', questionText: 'Solunumun en temel kası hangisidir?', options: ['İnterkostal kaslar', 'Rektus abdominis', 'Diyafram', 'Serratus anterior'], correctAnswer: 'Diyafram', latinTerm: 'Diaphragma', explanation: 'Diyafram, göğüs ve karın boşluğunu ayıran kubbe şekilli kastır. Kasılınca düzleşir ve akciğerlere hava çekilir (inspirasyon).'),
    Question(id: 'aex_039', category: 'anatomy', subcategory: 'muscular_system', type: 'test', difficulty: 'hard', questionText: 'Diyafram hangi sinir tarafından innerve edilir?', options: ['N. intercostalis', 'N. phrenicus', 'N. vagus', 'N. thoracicus longus'], correctAnswer: 'N. phrenicus', latinTerm: 'Nervus phrenicus', explanation: 'N. phrenicus (C3-C4-C5 köklerinden) diyaframı innerve eder. "C3, 4, 5 keeps the diaphragm alive" klinikte önemli bir ezberdir.'),
    Question(id: 'aex_040', category: 'anatomy', subcategory: 'muscular_system', type: 'test', difficulty: 'medium', questionText: 'Omuz abdüksiyonunun ilk 15 derecesini başlatan kas hangisidir?', options: ['Deltoid', 'Supraspinatus', 'Trapezius', 'Infraspinatus'], correctAnswer: 'Supraspinatus', latinTerm: 'M. supraspinatus', explanation: 'Supraspinatus, omuz abdüksiyonunu başlatan (ilk 15°) kastır. Sonra deltoid devralır. Supraspinatus tendonu en sık yırtılan rotator manşet tendonudur.'),
    Question(id: 'aex_041', category: 'anatomy', subcategory: 'muscular_system', type: 'test', difficulty: 'medium', questionText: 'Rotator manşet kaslarını hatırlamak için kullanılan SITS kısaltması hangi kasları ifade eder?', options: ['Serratus, Infraspinatus, Triceps, Subscapularis', 'Supraspinatus, Infraspinatus, Teres minor, Subscapularis', 'Supraspinatus, Iliopsoas, Trapezius, Sartorius', 'Sternocleidomastoid, Infraspinatus, Temporalis, Soleus'], correctAnswer: 'Supraspinatus, Infraspinatus, Teres minor, Subscapularis', explanation: 'SITS: Supraspinatus (abdüksiyon başlatır), Infraspinatus (dış rotasyon), Teres minor (dış rotasyon), Subscapularis (iç rotasyon). Omuz stabilitesini sağlarlar.'),
    Question(id: 'aex_042', category: 'anatomy', subcategory: 'muscular_system', type: 'test', difficulty: 'medium', questionText: 'El bileğini fleksiyona getiren ana kaslardan biri hangisidir?', options: ['Extensor carpi radialis', 'Flexor carpi radialis', 'Extensor digitorum', 'Brachioradialis'], correctAnswer: 'Flexor carpi radialis', latinTerm: 'M. flexor carpi radialis', explanation: 'Flexor carpi radialis ve flexor carpi ulnaris, el bileğinin fleksörüdür. Humerusun medial epikondilinden (common flexor origin) başlarlar.'),
    Question(id: 'aex_043', category: 'anatomy', subcategory: 'muscular_system', type: 'test', difficulty: 'hard', questionText: 'Lateral epikondilit (tenis dirseği) hangi kas grubunun aşırı kullanımıyla ilişkilidir?', options: ['El bileği fleksörleri', 'El bileği ekstensörleri', 'Dirsek fleksörleri', 'Omuz rotatorları'], correctAnswer: 'El bileği ekstensörleri', explanation: 'Lateral epikondilit, el bileği ekstensör kaslarının humerus lateral epikondiline tutunduğu yerdeki enflamasyondur. Tekrarlayan bilek ekstansiyonuyla oluşur.'),
    Question(id: 'aex_044', category: 'anatomy', subcategory: 'muscular_system', type: 'test', difficulty: 'medium', questionText: 'Gluteus medius kasının felcinde görülen yürüyüş bozukluğuna ne ad verilir?', options: ['Stepaj yürüyüşü', 'Trendelenburg yürüyüşü', 'Ataksik yürüyüş', 'Parkinson yürüyüşü'], correctAnswer: 'Trendelenburg yürüyüşü', latinTerm: 'M. gluteus medius', explanation: 'Gluteus medius pelvisin yatay dengesini sağlar. Felcinde tek ayak üzerinde dururken karşı taraf pelvis düşer (Trendelenburg belirtisi pozitif).'),
    Question(id: 'aex_045', category: 'anatomy', subcategory: 'muscular_system', type: 'test', difficulty: 'hard', questionText: 'N. peroneus communis (fibular sinir) felcinde ne görülür?', options: ['Pençe el', 'Düşük ayak (foot drop)', 'Düşük el (wrist drop)', 'Trendelenburg belirtisi'], correctAnswer: 'Düşük ayak (foot drop)', latinTerm: 'Nervus peroneus communis', explanation: 'N. peroneus communis, fibula başı çevresinde yüzeyel seyreder. Hasarında ayak dorsifleksörleri ve evertörleri felce uğrar, düşük ayak (foot drop) gelişir.'),

    // ============================================================
    // ORGAN DETAY - SİNDİRİM (12 soru)
    // ============================================================
    Question(id: 'aex_046', category: 'anatomy', subcategory: 'organs', type: 'test', difficulty: 'medium', questionText: 'Midenin hangi kısmı özofagus ile birleşir?', options: ['Pylor', 'Fundus', 'Kardia', 'Antrum'], correctAnswer: 'Kardia', latinTerm: 'Cardia', explanation: 'Kardia, midenin özofagus ile birleştiği giriş bölümüdür. Gastroözofageal bileşke (GEJ) burada yer alır.'),
    Question(id: 'aex_047', category: 'anatomy', subcategory: 'organs', type: 'test', difficulty: 'medium', questionText: 'İnce bağırsağın en kısa bölümü hangisidir?', options: ['Jejunum', 'İleum', 'Duodenum', 'Çekum'], correctAnswer: 'Duodenum', latinTerm: 'Duodenum', explanation: 'Duodenum yaklaşık 25 cm ile ince bağırsağın en kısa bölümüdür. Retroperitonealdir (periton arkası). Safra ve pankreas salgıları buraya dökülür.'),
    Question(id: 'aex_048', category: 'anatomy', subcategory: 'organs', type: 'test', difficulty: 'hard', questionText: 'B12 vitamini ve safra tuzlarının emildiği ince bağırsak bölümü hangisidir?', options: ['Duodenum', 'Jejunum', 'İleum', 'Çekum'], correctAnswer: 'İleum', latinTerm: 'Ileum', explanation: 'İleum, ince bağırsağın en uzun ve son bölümüdür. B12 vitamini ve safra tuzlarının spesifik emilim yeridir. Peyer plakları (lenfoid doku) burada yoğundur.'),
    Question(id: 'aex_049', category: 'anatomy', subcategory: 'organs', type: 'test', difficulty: 'medium', questionText: 'Kalın bağırsağın bölümlerinin doğru sıralaması hangisidir?', options: ['Çekum-Kolon asendens-Kolon transversum-Kolon desendens-Sigmoid-Rektum', 'Rektum-Sigmoid-Kolon-Çekum', 'Kolon asendens-Çekum-Kolon transversum-Rektum', 'Duodenum-Çekum-Kolon-Rektum'], correctAnswer: 'Çekum-Kolon asendens-Kolon transversum-Kolon desendens-Sigmoid-Rektum', explanation: 'Kalın bağırsak sırasıyla: Çekum → Kolon asendens → Kolon transversum → Kolon desendens → Sigmoid kolon → Rektum → Anal kanal.'),
    Question(id: 'aex_050', category: 'anatomy', subcategory: 'organs', type: 'test', difficulty: 'hard', questionText: 'McBurney noktası hangi organın yüzeyel projeksiyonunu gösterir?', options: ['Safra kesesi', 'Apendiks', 'Dalak', 'Böbrek'], correctAnswer: 'Apendiks', latinTerm: 'Appendix vermiformis', explanation: 'McBurney noktası, umbilikus ile spina iliaca anterior superior arasındaki hattın dış 1/3 ile iç 2/3 birleşim noktasıdır. Apendisit tanısında kullanılır.'),

    // ============================================================
    // ORGAN DETAY - KARDİYOVASKÜLER (10 soru)
    // ============================================================
    Question(id: 'aex_051', category: 'anatomy', subcategory: 'organs', type: 'test', difficulty: 'medium', questionText: 'Kalp duvarının en kalın tabakası hangisidir?', options: ['Endokard', 'Miyokard', 'Epikard', 'Perikard'], correctAnswer: 'Miyokard', latinTerm: 'Myocardium', explanation: 'Miyokard, kalp duvarının kas tabakasıdır ve en kalın tabakadır. Sol ventrikülde en kalındır. Endokard iç astar, epikard dış astardır.'),
    Question(id: 'aex_052', category: 'anatomy', subcategory: 'organs', type: 'test', difficulty: 'medium', questionText: 'Sol atrium ile sol ventrikül arasındaki kapağa ne denir?', options: ['Triküspit kapak', 'Mitral (biküspit) kapak', 'Aort kapağı', 'Pulmoner kapak'], correctAnswer: 'Mitral (biküspit) kapak', latinTerm: 'Valva mitralis', explanation: 'Mitral kapak (biküspit=iki yaprakçıklı), sol atrium ve sol ventrikül arasındadır. Kalpteki tek iki yaprakçıklı kapaktır.'),
    Question(id: 'aex_053', category: 'anatomy', subcategory: 'organs', type: 'test', difficulty: 'hard', questionText: 'Sol koroner arterin iki ana dalı hangileridir?', options: ['Sağ koroner ve sol koroner', 'LAD ve Sirkumfleks', 'Sağ marjinal ve posterior desandan', 'Anterior ve posterior interventriküler'], correctAnswer: 'LAD ve Sirkumfleks', latinTerm: 'A. coronaria sinistra', explanation: 'Sol koroner arter ikiye ayrılır: LAD (Left Anterior Descending / Ramus interventricularis anterior) ve LCx (Circumflex). LAD kalbin ön yüzünü besler.'),
    Question(id: 'aex_054', category: 'anatomy', subcategory: 'organs', type: 'test', difficulty: 'hard', questionText: 'Aort kavisinden çıkan üç ana dal sırasıyla hangileridir?', options: ['Sol karotis, sol subklavian, brakiosefalik', 'Brakiosefalik trunkus, sol a. carotis communis, sol a. subclavia', 'Sol vertebral, sağ karotis, sol subklavian', 'Sağ subklavian, sol karotis, sol vertebral'], correctAnswer: 'Brakiosefalik trunkus, sol a. carotis communis, sol a. subclavia', latinTerm: 'Arcus aortae', explanation: 'Aort kavisi dalları soldan sağa: 1) Truncus brachiocephalicus (sağ a. carotis communis + sağ a. subclavia), 2) Sol a. carotis communis, 3) Sol a. subclavia.'),

    // ============================================================
    // SİNİR SİSTEMİ DETAY (15 soru)
    // ============================================================
    Question(id: 'aex_055', category: 'anatomy', subcategory: 'nervous_system', type: 'test', difficulty: 'medium', questionText: '12 çift kranial sinirden sadece duyusal olanlar hangileridir?', options: ['I, II, VIII', 'III, IV, VI', 'V, VII, IX', 'X, XI, XII'], correctAnswer: 'I, II, VIII', explanation: 'Sadece duyusal kranial sinirler: I (Olfaktorius-koku), II (Optikus-görme), VIII (Vestibulokoklear-işitme/denge). Diğerleri motor veya mikst.'),
    Question(id: 'aex_056', category: 'anatomy', subcategory: 'nervous_system', type: 'test', difficulty: 'hard', questionText: 'Beyin sapının bölümleri yukarıdan aşağıya doğru hangileridir?', options: ['Medulla-Pons-Mesencephalon', 'Mesencephalon-Pons-Medulla oblongata', 'Pons-Mesencephalon-Medulla', 'Medulla-Mesencephalon-Pons'], correctAnswer: 'Mesencephalon-Pons-Medulla oblongata', explanation: 'Beyin sapı yukarıdan aşağıya: Mesencephalon (orta beyin) → Pons (köprü) → Medulla oblongata (omurilik soğanı). Hayati merkezler (solunum, kalp) medulladadır.'),
    Question(id: 'aex_057', category: 'anatomy', subcategory: 'nervous_system', type: 'test', difficulty: 'medium', questionText: 'Beynin sağ ve sol hemisferleri arasındaki bağlantıyı sağlayan kalın sinir lifi demetine ne denir?', options: ['Forniks', 'Corpus callosum', 'Capsula interna', 'Corona radiata'], correctAnswer: 'Corpus callosum', latinTerm: 'Corpus callosum', explanation: 'Corpus callosum (nasırlı cisim), sağ ve sol serebral hemisferleri birbirine bağlayan en büyük komissüral lif demetidir.'),
    Question(id: 'aex_058', category: 'anatomy', subcategory: 'nervous_system', type: 'test', difficulty: 'hard', questionText: 'Broca alanı hangi lobda bulunur ve hasarında ne olur?', options: ['Temporal lob - Anlama bozukluğu', 'Frontal lob - Motor (ekspresif) afazi', 'Parietal lob - Duyu kaybı', 'Oksipital lob - Körlük'], correctAnswer: 'Frontal lob - Motor (ekspresif) afazi', latinTerm: 'Area Brocae', explanation: 'Broca alanı sol frontal lobdadır. Hasarında hasta anlar ama konuşamaz (motor/ekspresif afazi). Kısa, çabalı, telgrafik konuşma görülür.'),
    Question(id: 'aex_059', category: 'anatomy', subcategory: 'nervous_system', type: 'test', difficulty: 'hard', questionText: 'Bazal ganglionlar hangi fonksiyonda önemlidir?', options: ['Görme', 'İstemsiz hareket kontrolü ve motor planlama', 'İşitme', 'Solunum düzenleme'], correctAnswer: 'İstemsiz hareket kontrolü ve motor planlama', explanation: 'Bazal ganglionlar (kaudat nükleus, putamen, globus pallidus) istemli hareketin planlanması ve düzenlenmesinde görev alır. Hasarında Parkinson veya Huntington hastalığı görülür.'),
    Question(id: 'aex_060', category: 'anatomy', subcategory: 'nervous_system', type: 'test', difficulty: 'medium', questionText: 'Hipotalamus hangi fonksiyonları kontrol eder?', options: ['Sadece görme', 'Vücut ısısı, açlık, susuzluk, uyku, hormon düzenleme', 'Sadece denge', 'Sadece hafıza'], correctAnswer: 'Vücut ısısı, açlık, susuzluk, uyku, hormon düzenleme', latinTerm: 'Hypothalamus', explanation: 'Hipotalamus, homeostazın ana kontrol merkezidir: Termoregülasyon, açlık-tokluk, su dengesi, sirkadiyen ritim, otonom sinir sistemi ve hipofiz bezi kontrolü.'),
    Question(id: 'aex_061', category: 'anatomy', subcategory: 'nervous_system', type: 'test', difficulty: 'hard', questionText: 'Plexus brachialis hangi spinal sinir köklerinden oluşur?', options: ['C1-C4', 'C5-T1', 'T1-T6', 'L1-L4'], correctAnswer: 'C5-T1', latinTerm: 'Plexus brachialis', explanation: 'Plexus brachialis C5-T1 köklerinden oluşur ve üst ekstremitenin motor ve duyusal innervasyonunu sağlar. Erb-Duchenne (üst) ve Klumpke (alt) felçleri bu pleksusun lezyonlarıdır.'),
    Question(id: 'aex_062', category: 'anatomy', subcategory: 'nervous_system', type: 'test', difficulty: 'hard', questionText: 'Plexus lumbosacralis hangi spinal sinir köklerinden oluşur?', options: ['C5-T1', 'T6-T12', 'L1-S3', 'S3-Co'], correctAnswer: 'L1-S3', latinTerm: 'Plexus lumbosacralis', explanation: 'Lumbosakral pleksus L1-S3 köklerinden oluşur. N. femoralis (L2-L4), N. obturatorius (L2-L4) ve N. ischiadicus (L4-S3) bu pleksustan çıkar.'),
  ];
}
